// Convierte el pedido del panel en una fila por producto
const o = $input.first().json.body || {};
if (!o.numero || !Array.isArray(o.items) || !o.items.length) {
  throw new Error('Pedido inválido: falta número u productos');
}
const c = o.cliente || {};
const fecha = (iso) => iso ? new Date(iso).toLocaleString('es-CO', { timeZone: 'America/Bogota', dateStyle: 'short', timeStyle: 'short' }) : '';

return o.items.map((it) => ({
  json: {
    'ID línea': it.idLinea,
    'Registrada': fecha(o.registrada),
    'N.º orden': o.numero,
    'Fecha orden': o.fechaOrden || '',
    'Cliente': c.nombre || '',
    'Celular': c.telefono || '',
    'Ciudad': c.ciudad || '',
    'Dirección': c.direccion || '',
    'Barrio': c.barrio || '',
    'Método de pago': c.metodoPago || '',
    'Notas': c.notas || '',
    'Producto': it.producto,
    'Tono': it.tono,
    'Cantidad': it.cantidad,
    'Precio unitario': it.precio,
    'Total línea': it.total,
    'Subtotal pedido': o.subtotal,
    'Envío': o.envio,
    'Total pedido': o.total,
    'Stock descontado': it.stockDescontado ? 'Sí' : 'No'
  }
}));
